async function main(ctx) {
  const input = ctx.input || {};

  const beforeId = input.beforeId ?? undefined;
  const beforeUpdatedAt = input.beforeUpdatedAt ?? undefined;

  const hasBeforeId = typeof beforeId === 'string' && beforeId.trim().length > 0;
  const hasBeforeUpdatedAt = typeof beforeUpdatedAt === 'string' && beforeUpdatedAt.trim().length > 0;
  if (hasBeforeId !== hasBeforeUpdatedAt) {
    throw new Error('beforeId and beforeUpdatedAt must be provided together');
  }

  const limitRaw = input.limit;
  const limit = limitRaw === undefined || limitRaw === null || limitRaw === '' ? undefined : Number(limitRaw);
  if (limit !== undefined && (!Number.isFinite(limit) || limit <= 0)) {
    throw new Error('limit must be a positive number');
  }

  const qRaw = (input.q ?? '').toString().trim();
  const q = qRaw.length ? qRaw : undefined;

  const conversationIdRaw = input.conversationId ?? input.parentConversationId ?? input.id ?? ctx.env('CONVERSATION_ID') ?? undefined;
  const conversationId = conversationIdRaw === undefined ? '' : String(conversationIdRaw).trim();
  if (!conversationId) throw new Error('conversationId is required (or provide runtime CONVERSATION_ID)');

  const args = {
    conversationId,
    limit,
    q,
    beforeId: hasBeforeId ? String(beforeId) : undefined,
    beforeUpdatedAt: hasBeforeUpdatedAt ? String(beforeUpdatedAt) : undefined
  };

  for (const k of Object.keys(args)) {
    if (args[k] === undefined) delete args[k];
  }

  return args;
}

async function main(ctx) {
  const resp = ctx.input || {};
  const body = resp.body;
  if (body && typeof body === 'object' && body.success === true && 'data' in body) return body.data;
  return body ?? resp;
}
